import { UniverseChainId } from "uniswap/src/features/chains/types";
const CloseIcon = styled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const ReviewCard = styled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing8",
  width: "100%",
  marginBottom: "$spacing24"
});
const PairHeader = styled(Flex, {
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap8",
  marginBottom: "$spacing24"
});
const Badge = styled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$rounded8",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8"
});
const ArrowPill = styled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  padding: "$spacing4",
  alignItems: "center",
  justifyContent: "center",
  width: 24,
  height: 24
});
const UsdPill = styled(Flex, {
  backgroundColor: "$surface3",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  borderRadius: "$rounded12",
  justifyContent: "center",
  alignItems: "center",
  marginLeft: "$spacing8"
});
const Divider = styled(Flex, {
  height: 1,
  backgroundColor: "$surface3",
  width: "100%",
  marginVertical: "$spacing16"
});
const InfoRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing12"
});
const ConfirmButton = styled(Button, {
  width: "100%",
  borderRadius: "$rounded20",
  height: "56px",
  py: "$spacing24"
});
export default function BorrowReviewModal({
  isOpen,
  onClose,
  onConfirm,
  collateralAmount,
  borrowAmount,
  collateralToken,
  borrowToken
}) {
  const colors = useSporeColors();
  const parsedCollateral = parseFloat(collateralAmount) || 0;
  const collateralUsd = parsedCollateral * collateralToken.price;
  const prevCollateral = 0;
  const newCollateral = parsedCollateral;
  const prevLoan = 0;
  const newLoan = parseFloat(borrowAmount) || 0;
  return <Modal
    name={"BorrowReviewModal"}
    isModalOpen={isOpen}
    onClose={onClose}
    backgroundColor={colors.surface1.val}
    maxWidth={480}
    padding="$spacing24"
  >
      <ModalHeader>
        <Text variant="heading2" color="$neutral1">
          Review
        </Text>
        <CloseIcon onPress={onClose}>
          <X size={24} color={colors.neutral2.val} />
        </CloseIcon>
      </ModalHeader>

      <ReviewCard>
        {
    /* Pair Header */
  }
        <PairHeader>
          <Flex flexDirection="row" alignItems="center" mr="$spacing4">
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={24}
    style={{ marginRight: -8, zIndex: 2 }}
  />
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.symbol ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={24}
    style={{ zIndex: 1 }}
  />
          </Flex>
          <Text variant="heading3" color="$neutral1">
            {collateralToken.symbol} / {borrowToken.symbol}
          </Text>
          <Badge>
            <Text variant="body4" color="$neutral2">
              62.5%
            </Text>
          </Badge>
          <ArrowPill>
            <ArrowUpRight size={12} color={colors.neutral2.val} />
          </ArrowPill>
        </PairHeader>

        <Text variant="body2" color="$neutral2" mb="$spacing8">
          Supply Collateral
        </Text>

        <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
          <Flex flexDirection="row" alignItems="center">
            <Text variant="heading2" color="$neutral1">
              {parsedCollateral}
            </Text>
            <Text variant="heading2" color="$neutral2" ml="$spacing4">
              {collateralToken.symbol}
            </Text>
            <UsdPill>
              <Text variant="body3" color="$neutral2">
                ${collateralUsd.toFixed(2)}
              </Text>
            </UsdPill>
          </Flex>
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={24}
  />
        </Flex>

        <Divider />

        {
    /* Stats Grid */
  }
        <InfoRow>
          <Text variant="body2" color="$neutral2">
            Collateral ({collateralToken.symbol})
          </Text>
          <Flex flexDirection="row" alignItems="center" gap="$gap4">
            <Text variant="body2" color="$neutral2">
              {prevCollateral.toFixed(2)}
            </Text>
            <Text variant="body2" color="$neutral2">
              →
            </Text>
            <Text variant="body2" color="$neutral1">
              {newCollateral}
            </Text>
          </Flex>
        </InfoRow>

        <InfoRow>
          <Text variant="body2" color="$neutral2">
            Loan ({borrowToken.symbol})
          </Text>
          <Flex flexDirection="row" alignItems="center" gap="$gap4">
            <Text variant="body2" color="$neutral2">
              {prevLoan.toFixed(2)}
            </Text>
            <Text variant="body2" color="$neutral2">
              →
            </Text>
            <Text variant="body2" color="$neutral1">
              {newLoan.toFixed(2)}
            </Text>
          </Flex>
        </InfoRow>

        <InfoRow>
          <Text variant="body2" color="$neutral2">
            Rate
          </Text>
          <Text variant="body2" color="$neutral1">
            14.59%
          </Text>
        </InfoRow>

        <InfoRow style={{ marginBottom: 0 }}>
          <Text variant="body2" color="$neutral2">
            LTV / Liq. LTV
          </Text>
          <Text variant="body2" color="$neutral1">
            0% / 62.5%
          </Text>
        </InfoRow>
      </ReviewCard>

      <ConfirmButton onPress={onConfirm}>Confirm</ConfirmButton>
    </Modal>;
}
