"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { useEffect, useState } from "react";
import { ArrowUpRight, X } from "react-feather";
import { Button, Flex, SpinningLoader, Text, styled, useSporeColors } from "ui/src";
import { Modal } from "uniswap/src/components/modals/Modal";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
const CloseIcon = styled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const SummaryCard = styled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing8",
  width: "100%",
  marginBottom: "$spacing24"
});
const PairHeader = styled(Flex, {
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap8",
  marginBottom: "$spacing24"
});
const Badge = styled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$rounded8",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8"
});
const ArrowPill = styled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  padding: "$spacing4",
  alignItems: "center",
  justifyContent: "center",
  width: 24,
  height: 24
});
const UsdPill = styled(Flex, {
  backgroundColor: "$surface3",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  borderRadius: "$rounded12",
  justifyContent: "center",
  alignItems: "center",
  marginLeft: "$spacing8"
});
const PermitSection = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  marginBottom: "$spacing24"
});
const AddressPill = styled(Flex, {
  backgroundColor: "$surface2",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  borderRadius: "$rounded12",
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap4",
  marginLeft: "$spacing8"
});
const ProgressRow = styled(Flex, {
  flexDirection: "row",
  width: "100%",
  gap: "$gap8",
  marginBottom: "$spacing12"
});
const ProgressSegment = styled(Flex, {
  height: "4px",
  borderRadius: "$roundedFull",
  flex: 1,
  variants: {
    status: {
      active: { backgroundColor: "$accent1" },
      // Blue
      completed: { backgroundColor: "$greenVibrant" },
      // Green (assuming variable exists)
      pending: { backgroundColor: "$surface3" }
      // Gray
    }
  }
});
const FooterRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%"
});
const ExplorerLink = styled(Flex, {
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap4",
  cursor: "pointer"
});
const DoneButton = styled(Button, {
  width: "100%",
  borderRadius: "$rounded20",
  py: "$spacing24",
  marginBottom: "$spacing16"
});
export default function BorrowConfirmModal({
  isOpen,
  onClose,
  collateralAmount,
  borrowAmount,
  collateralToken,
  borrowToken
}) {
  const colors = useSporeColors();
  const [step, setStep] = useState(1);
  const parsedCollateral = parseFloat(collateralAmount) || 0;
  const collateralUsd = parsedCollateral * collateralToken.price;
  useEffect(() => {
    if (isOpen) {
      if (step === 1) {
        const timer = setTimeout(() => setStep(2), 3e3);
        return () => clearTimeout(timer);
      } else if (step === 2) {
        const timer = setTimeout(() => setStep(3), 3e3);
        return () => clearTimeout(timer);
      }
    } else {
      setStep(1);
    }
    return void 0;
  }, [isOpen, step]);
  const stepText = step === 1 ? "Enable permit2 contract" : "Execute transaction";
  const addressText = step === 1 ? "0xb98c...746A" : "0x6BFd...20C4";
  const showProgress = step < 3;
  return <Modal
    name={"BorrowConfirmModal"}
    isModalOpen={isOpen}
    onClose={onClose}
    backgroundColor={colors.surface1.val}
    maxWidth={480}
    padding="$spacing24"
  >
      <ModalHeader>
        <Text variant="heading2" color="$neutral1">
          Confirm
        </Text>
        <CloseIcon onPress={onClose}>
          <X size={24} color={colors.neutral2.val} />
        </CloseIcon>
      </ModalHeader>

      <SummaryCard>
        {
    /* Pair Header */
  }
        <PairHeader>
          <Flex flexDirection="row" alignItems="center" mr="$spacing4">
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={24}
    style={{ marginRight: -8, zIndex: 2 }}
  />
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.symbol ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={24}
    style={{ zIndex: 1 }}
  />
          </Flex>
          <Text variant="heading3" color="$neutral1">
            {collateralToken.symbol} / {borrowToken.symbol}
          </Text>
          <Badge>
            <Text variant="body4" color="$neutral2">
              62.5%
            </Text>
          </Badge>
          <ArrowPill>
            <ArrowUpRight size={12} color={colors.neutral2.val} />
          </ArrowPill>
        </PairHeader>

        <Text variant="body2" color="$neutral2" mb="$spacing8">
          Supply Collateral
        </Text>

        <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
          <Flex flexDirection="row" alignItems="center">
            <Text variant="heading2" color="$neutral1">
              {parsedCollateral}
            </Text>
            <Text variant="heading2" color="$neutral2" ml="$spacing4">
              {collateralToken.symbol}
            </Text>
            <UsdPill>
              <Text variant="body3" color="$neutral2">
                ${collateralUsd.toFixed(2)}
              </Text>
            </UsdPill>
          </Flex>
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={24}
  />
        </Flex>
      </SummaryCard>

      {showProgress ? <>
          <PermitSection>
            <Flex flexDirection="row" alignItems="center">
              <Text variant="body2" color="$neutral1">
                {stepText}
              </Text>
              <AddressPill>
                <Text variant="body4" color="$neutral2">
                  {addressText}
                </Text>
                <ArrowUpRight size={12} color={colors.neutral2.val} />
              </AddressPill>
            </Flex>
            {
    /* Status Circle / Spinner */
  }
            {
    /* In screenshot it's a blue check for completed? Or spinner for active? 
       Let's use spinner for now and checkmark for step 1 when done in step 2. */
  }
            <SpinningLoader size={20} color={colors.accent1.val} />
          </PermitSection>

          <ProgressRow>
            {
    /* Segment 1: Active in step 1, Completed in step 2 */
  }
            <ProgressSegment
    status={step === 1 ? "active" : "completed"}
    style={step === 2 ? { backgroundColor: "#48C28D" } : {}}
  />
            {
    /* Segment 2: Pending in step 1, Active in step 2 */
  }
            <ProgressSegment status={step === 1 ? "pending" : "active"} />
          </ProgressRow>
        </> : <DoneButton onPress={onClose}>Done</DoneButton>}

      <FooterRow>
        {step < 3 ? <Text variant="body3" color="$neutral2">
            {step === 1 ? "Signature pending..." : "Signature successfully processed"}
          </Text> : <Text variant="body3" color="$neutral2">
            Transaction complete!
          </Text>}

        <ExplorerLink>
          <Text variant="body3" color="$neutral2">
            View on explorer
          </Text>
          <ArrowUpRight size={14} color={colors.neutral2.val} />
        </ExplorerLink>
      </FooterRow>
    </Modal>;
}
